-- The SWISSCUT code key (Code keys -> Parting -> SWISSCUT), from the ISCAR
-- e-catalog's SWISSCUT families (SCI 22 / SCI 41 inserts, SCHR/L holders);
-- kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.swisscut', $ck${"title": "SWISSCUT code key – inserts and tools", "subtitle": "Inserts (SCI 22, SCI 41 extra long) for grooving, parting, turning and back turning on Swiss-type and automatic machines, and their holders", "example": "SCIL 22-050L12-00", "decoder": "swisscut", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "SCI", "rows": [{"code": "SCI", "meaning": "SWISSCUT insert"}]}, {"key": "i-hand", "title": "Insert – hand", "sample": "L", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-size", "title": "Insert – series", "sample": "22", "rows": [{"code": "22", "meaning": "SCI 22 (SCHR/L-22BF holders)"}, {"code": "41", "meaning": "SCI 41, extra long (SCHR/L-41BF holders)"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "050", "rows": [{"code": "###", "meaning": "Grooving / parting: cutting width x 100 (e.g. 050 = 0.50 mm)"}, {"code": "##", "meaning": "Turning / back turning: cutting width x 10 (e.g. 05 = 0.5 mm)"}]}, {"key": "i-lead", "title": "Insert – lead angle", "sample": "L12", "rows": [{"code": "N", "meaning": "Neutral (no lead angle)"}, {"code": "R##", "meaning": "Lead angle in degrees, right (e.g. R12)"}, {"code": "L##", "meaning": "Lead angle in degrees, left (e.g. L16)"}]}, {"key": "i-chip", "title": "Chipformer", "rows": [{"code": "NP", "meaning": "Grooving, turning and parting inserts (e.g. SCIL 22-100NP08)"}, {"code": "NX", "meaning": "Grooving and turning inserts with a chipformer (corner radius x1000, e.g. 080 = 0.08 mm)"}]}, {"key": "i-type", "title": "Insert – turning type", "rows": [{"code": "B", "meaning": "Back turning"}, {"code": "BA", "meaning": "Back turning, A version (BRA / BLA)"}, {"code": "E", "meaning": "Back turning for short chipping materials"}, {"code": "EA", "meaning": "Back turning for short chipping materials, A version (ERA / ELA)"}, {"code": "A", "meaning": "Turning with a front relief angle"}]}, {"key": "i-dir", "title": "Insert – turning direction", "rows": [{"code": "R", "meaning": "Right"}, {"code": "L", "meaning": "Left"}, {"code": "D", "meaning": "Both directions (AD) (inferred)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "00", "rows": [{"code": "##", "meaning": "Corner radius x 100 (e.g. 10 = 0.10 mm; 00 = sharp)"}, {"code": "###", "meaning": "NX: corner radius x 1000 (e.g. 080 = 0.08 mm)"}]}, {"key": "i-rake", "title": "Insert – rake angle", "rows": [{"code": "K#", "meaning": "Rake angle (GAN) in degrees (e.g. K7 = 7°)"}, {"code": "K##", "meaning": "Rake angle (GAN) in degrees (e.g. K15 = 15°)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "SCH", "meaning": "Grooving and turning tools with back and front clamping for Swiss-type and automatic machines (SCHR / SCHL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank size in mm (e.g. 10, 12, 16)"}, {"code": "####", "meaning": "Shank height x width (e.g. 0810 = 8 x 10 mm)"}]}, {"key": "t-seat", "title": "Tool – insert series", "rows": [{"code": "22", "meaning": "For SCI 22 inserts"}, {"code": "41", "meaning": "For SCI 41 inserts"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "BF", "meaning": "Back and front clamping"}, {"code": "JHP", "meaning": "Channels for high-pressure coolant"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
